 core_atoms=[{'map':1,'element':'P','role':'central'}]+[{'map':i,'element':'Al','role':'shell'} for i in range(2,14)]
 ligands=[]
 for label,offset in [('A',14),('B',48)]:
  atoms=[{'map':offset,'element':'B'}]+[{'map':i,'element':'C'} for i in range(offset+1,offset+19)]+[{'map':i,'element':'F'} for i in range(offset+19,offset+34)]
  bonds=[]
  for ring in range(3):
   cs=list(range(offset+1+6*ring,offset+7+6*ring));fs=list(range(offset+19+5*ring,offset+24+5*ring))
   bonds.append({'a':offset,'b':cs[0],'order':'SINGLE'})
   bonds.extend({'a':cs[i],'b':cs[(i+1)%6],'order':'AROMATIC'} for i in range(6))
   bonds.extend({'a':cs[i+1],'b':fs[i],'order':'SINGLE'} for i in range(5))
  ligands.append({'id':'ligand_'+label,'formula':'BC18F15','formal_charge':0,'atom_maps':[a['map'] for a in atoms],'atoms':atoms,'bonds':bonds,'attachment':'B approaches one chosen shell Al; attachment site/orientation is a search variable, not a fixed author winner.'})
 systems=[]
