 candidate=obj({'candidate_id':S,'n':enum(0,1,2),'charge':enum(0,-1),'multiplicity':enum(1,2,3,4,5,6),'site_class':S,'start_geometry_file':P,'final_geometry_file':P,'job_id':S,'status':enum('retained','collapsed','reconstructed','failed'),'core_and_ligand_graph_file':P,'selection_reason':S})
